41	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type] ?? 0;
42	
43	const CURSE_SURCHARGE_RATE = 0.5;
44	const HIGH_ENCHANTMENT_LEVEL = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
46	
47	const isCursed = (item: Item): boolean => item.cursed === true;
48	const isHighlyEnchanted = (item: Item): boolean =>
49	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
50	
51	/** Item-specific modifiers apply to the base premium of the affected item only. */
52	const itemSurchargesOf = (item: Item): number => {
53	  const basePremium = basePremiumOfType(item.type);
54	  const curseSurcharge = isCursed(item) ? basePremium * CURSE_SURCHARGE_RATE : 0;
55	  const highEnchantmentSurcharge = isHighlyEnchanted(item)
56	    ? basePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
57	    : 0;
58	  return curseSurcharge + highEnchantmentSurcharge;
59	};
60	
61	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
62	const COMPONENT_BLOCK_SIZE = 3;
63	const COMPONENT_BLOCK_PREMIUM = 60;
64	
65	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
66	
67	const countByType = (items: Item[]): Map<string, number> => {
68	  const counts = new Map<string, number>();
69	  for (const item of items) {
70	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
71	  }
72	  return counts;
73	};
74	
75	/**
76	 * Items of one type are normally priced individually. The exception is
77	 * components: exactly 3 alike ones form a "building block" priced as a unit.
78	 */
79	const typeGroupPremium = (type: string, count: number): number =>
80	  isComponent(type) && count === COMPONENT_BLOCK_SIZE
81	    ? COMPONENT_BLOCK_PREMIUM
82	    : count * basePremiumOfType(type);
83	
84	const policyBasePremiumOf = (step: QuoteStep): number =>
85	  [...countByType(step.items)].reduce(
86	    (sum, [type, count]) => sum + typeGroupPremium(type, count),
87	    0,
88	  );
89	
90	const isLongStanding = (customer: Customer): boolean =>
91	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
92	
93	/**
94	 * Policy-wide modifiers are signed rates charged against the policy base
95	 * premium: surcharges positive, discounts negative.
96	 */
97	const policyModifierRateFor = (customer: Customer, isFollowUpContract: boolean): number =>
98	  INITIAL_ASSESSMENT_SURCHARGE_RATE -
99	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
100	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
101	
102	const itemSurchargesOfPolicy = (step: QuoteStep): number =>
103	  step.items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);
104	
105	/** Kept as an exact fraction — only the final premium is rounded. */
106	const premiumBeforeRounding = (
107	  step: QuoteStep,
108	  customer: Customer,
109	  isFollowUpContract: boolean,
110	): number => {
111	  const policyBasePremium = policyBasePremiumOf(step);
112	  const policyModifiers =
113	    policyBasePremium * policyModifierRateFor(customer, isFollowUpContract);
114	  return policyBasePremium + itemSurchargesOfPolicy(step) + policyModifiers + PROCESSING_FEE;
115	};
116	
117	/** Rounded up, in the MHPCO's favour. */
118	const finalPremiumFor = (
119	  step: QuoteStep,
120	  customer: Customer,
121	  isFollowUpContract: boolean,
122	): number => Math.ceil(premiumBeforeRounding(step, customer, isFollowUpContract));
123	
124	export const runScenario = (scenario: Scenario): ScenarioOutput => {
125	  let quotesSoFar = 0;
126	
127	  const results = scenario.steps.map((step) => {
128	    const premium = finalPremiumFor(step, scenario.customer, quotesSoFar > 0);
129	    quotesSoFar += 1;
130	    return { premium };
131	  });
132	
133	  return { results };
134	};
