/**
 * Policy-wide modifiers are signed rates charged against the policy base
 * premium: surcharges positive, discounts negative.
 */
const policyModifierRateFor = (customer: Customer, isFollowUpContract: boolean): number =>
  INITIAL_ASSESSMENT_SURCHARGE_RATE -
  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);

const itemSurchargesOfPolicy = (step: QuoteStep): number =>
  step.items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);

/** Kept as an exact fraction — only the final premium is rounded. */
const premiumBeforeRounding = (
  step: QuoteStep,
  customer: Customer,
  isFollowUpContract: boolean,
): number => {
  const policyBasePremium = policyBasePremiumOf(step);
  const policyModifiers =
    policyBasePremium * policyModifierRateFor(customer, isFollowUpContract);
  return policyBasePremium + itemSurchargesOfPolicy(step) + policyModifiers + PROCESSING_FEE;
};

/** Rounded up, in the MHPCO's favour. */
const finalPremiumFor = (
  step: QuoteStep,
  customer: Customer,
  isFollowUpContract: boolean,
): number => Math.ceil(premiumBeforeRounding(step, customer, isFollowUpContract));

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  let quotesSoFar = 0;

  const results = scenario.steps.map((step) => {
    const premium = finalPremiumFor(step, scenario.customer, quotesSoFar > 0);
    quotesSoFar += 1;
    return { premium };
  });

  return { results };
};

