/** What the policy-wide modifiers are judged against, beyond the items themselves. */
interface QuoteContext {
  customer: Customer;
  isFollowUpContract: boolean;
}

/**
 * Policy-wide modifiers are signed rates charged against the policy base
 * premium: surcharges positive, discounts negative.
 */
const policyModifierRateFor = (context: QuoteContext): number =>
  INITIAL_ASSESSMENT_SURCHARGE_RATE -
  (isLongStanding(context.customer) ? LOYALTY_DISCOUNT_RATE : 0) -
  (context.isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);

const itemSurchargesOfPolicy = (step: QuoteStep): number =>
  step.items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);

/** Kept as an exact fraction — only the final premium is rounded. */
const premiumBeforeRounding = (step: QuoteStep, context: QuoteContext): number => {
  const policyBasePremium = policyBasePremiumOf(step);
  const policyModifiers = policyBasePremium * policyModifierRateFor(context);
  return policyBasePremium + itemSurchargesOfPolicy(step) + policyModifiers + PROCESSING_FEE;
};

/** Rounded up, in the MHPCO's favour. */
const finalPremiumFor = (step: QuoteStep, context: QuoteContext): number =>
  Math.ceil(premiumBeforeRounding(step, context));

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  const results = scenario.steps.map((step, stepIndex) => {
    const isFollowUpContract = stepIndex > 0;
    return {
      premium: finalPremiumFor(step, { customer: scenario.customer, isFollowUpContract }),
    };
  });

  return { results };
};
